+pub(super) fn read_slot_i64(state: &RunState, slot: SlotIdx) -> RuntimeResult<i64> {
+    let SlotValue::I64(value) = state
+        .frame
+        .read_slot(slot)
+        .map_err(|_| RuntimeError::InvalidActionCompletion)?
+    else {
+        return Err(RuntimeError::InvalidActionCompletion);
+    };
+    Ok(*value)
+}
