 /// Fixed binary IPC frame header.
 #[derive(Debug, Clone, Copy, PartialEq, Eq)]
 pub struct IpcFrameHeader {
     /// IPC command kind.
     pub command: IpcCommand,
     /// Command-specific flags.
     pub flags: u16,
     /// Correlates requests and replies.
     pub correlation: u64,
     /// Postcard payload byte length.
     pub payload_len: u32,
