     /// Creates an IPC frame header.
     #[must_use]
     pub const fn new(command: IpcCommand, flags: u16, correlation: u64, payload_len: u32) -> Self {
         Self {
             command,
             flags,
             correlation,
             payload_len,
         }
     }

     /// Encodes the header using the §21 little-endian wire layout.
